-- bl_out_0236_broker_templates_pro — broker series rebuilt to big-brand standard.
-- Corporate voice ("we", LoadBoot Broker Partnerships — no "I run LoadBoot"), branded
-- HTML: navy header + white logo, blue→orange gradient bar, bulletproof CTA buttons,
-- signature block, gray compliance footer (FMCSA note · one-click unsub · postal address).
-- Self-contained by design (delivery-worker v15 never wraps outreach.*).
-- Also upgrades outreach_html_to_text: strips inline formatting (span/b/i/strong/em/u)
-- and the hidden preheader BEFORE anchor conversion, so button links keep their URLs
-- in the plain-text part even with color-durability <span>s inside <a> (v14 lesson).

create or replace function app_private.outreach_html_to_text(p_html text)
returns text language plpgsql immutable as $function$
declare h text := coalesce(p_html,'');
begin
  h := regexp_replace(h, '<div style="display:none[^>]*>[^<]*</div>', '', 'gi');
  h := regexp_replace(h, '</?(span|b|strong|i|em|u)[^>]*>', '', 'gi');
  h := regexp_replace(h, '<a[^>]*href="([^"]+)"[^>]*>([^<]*)</a>', '\2 (\1)', 'gi');
  h := regexp_replace(h, '<br[^>]*>', chr(10), 'gi');
  h := regexp_replace(h, '</p>', chr(10)||chr(10), 'gi');
  h := regexp_replace(h, '</td>\s*</tr>', chr(10), 'gi');
  h := regexp_replace(h, '<[^>]+>', '', 'g');
  h := replace(h, '&mdash;', '—'); h := replace(h, '&middot;', '·');
  h := replace(h, '&ldquo;', '"'); h := replace(h, '&rdquo;', '"');
  h := replace(h, '&lsquo;', ''''); h := replace(h, '&rsquo;', '''');
  h := replace(h, '&nbsp;', ' '); h := replace(h, '&bull;', '-');
  h := replace(h, '&rarr;', '->'); h := replace(h, '&amp;', '&');
  h := replace(h, '&iquest;', '¿'); h := replace(h, '&ntilde;', 'ñ');
  h := regexp_replace(h, '[ '||chr(9)||']+', ' ', 'g');
  h := regexp_replace(h, '('||chr(10)||' *){3,}', chr(10)||chr(10), 'g');
  return btrim(h);
end; $function$;

update app_private.outreach_templates set parts=null,
subject='Your loads, covered by FMCSA-verified carriers — free',
html=$T$<div style="display:none;max-height:0;overflow:hidden">Every carrier verified against FMCSA before they can bid. Posting is free.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:22px 36px"><img src="https://loadboot.com/email-logo-white-2x.png" width="150" alt="LoadBoot" style="display:block;border:0;max-width:150px;height:auto"></td></tr><tr><td style="height:4px;background:#0883F7;background:linear-gradient(90deg,#0883F7,#FC5305);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:32px 36px 6px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p><p style="margin:0 0 16px">LoadBoot is a freight technology platform where <b>every carrier is verified against FMCSA before they can bid</b> &mdash; operating authority, insurance on record, and the truck&rsquo;s VIN matched to its certificate of insurance. Posting loads is free, with no per-post fees.</p><p style="margin:0 0 16px">There are two ways to get started:</p><p style="margin:0 0 16px"><b>Automatic:</b> add <b>loads@loadboot.com</b> to the load list you already email your carriers. Your loads post to our board automatically, and your contact details stay on every load &mdash; nothing about your workflow changes.</p><p style="margin:0 0 16px"><b>Direct:</b> create a free broker account and manage everything from one screen &mdash; post, cover, send the rate confirmation, and invoice.</p></td></tr><tr><td align="left" style="padding:10px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d1&oc={OC}" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Create your free broker account</span></a></td></tr></table></td></tr><tr><td style="padding:12px 36px 6px;font-size:13.5px;line-height:1.7;color:#64748b">Prefer zero setup? Simply cc <b>loads@loadboot.com</b> on your next load blast &mdash; that is all it takes.</td></tr><tr><td style="padding:18px 36px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 36px 24px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Partnerships</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d1&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:16px 36px 20px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$T$
where audience='broker' and day=1;

update app_private.outreach_templates set parts=null,
subject='Five checks that stop double-brokering — run automatically',
html=$T$<div style="display:none;max-height:0;overflow:hidden">The carrier-vetting checklist professional brokerages use — automated at booking.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:22px 36px"><img src="https://loadboot.com/email-logo-white-2x.png" width="150" alt="LoadBoot" style="display:block;border:0;max-width:150px;height:auto"></td></tr><tr><td style="height:4px;background:#0883F7;background:linear-gradient(90deg,#0883F7,#FC5305);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:32px 36px 6px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p><p style="margin:0 0 16px">Freight fraud is at an all-time high, and most of it enters through a rushed carrier setup. These are the five checks professional brokerages run before tendering to a new carrier:</p><p style="margin:0 0 16px">1.&nbsp; Call the phone number on the carrier&rsquo;s FMCSA record &mdash; not the one in the email signature.<br>2.&nbsp; Request the COI from the insurance agent directly, and verify on the agency&rsquo;s public number.<br>3.&nbsp; Match the truck&rsquo;s VIN to the scheduled autos on that certificate.<br>4.&nbsp; Treat a young authority with a brand-new factoring notice and same-day urgency as a red flag.<br>5.&nbsp; Decline any carrier whose dispatcher will not take a short call about pickup details.</p><p style="margin:0 0 16px">On LoadBoot, <b>every one of these checks runs automatically at booking</b>. A carrier that fails cannot bid on your load &mdash; on your busiest day or your quietest one.</p></td></tr><tr><td align="left" style="padding:10px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/compliance.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">See how carrier verification works</span></a></td></tr></table></td></tr><tr><td style="padding:12px 36px 6px;font-size:13.5px;line-height:1.7;color:#64748b">Posting is free, permanently. <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="color:#0883F7">Create your free broker account</a>.</td></tr><tr><td style="padding:18px 36px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 36px 24px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Partnerships</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d2&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:16px 36px 20px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$T$
where audience='broker' and day=2;

update app_private.outreach_templates set parts=null,
subject='Live GPS on every load — retire the check call',
html=$T$<div style="display:none;max-height:0;overflow:hidden">One tracking link for your shipper. Geofenced timestamps on every load.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:22px 36px"><img src="https://loadboot.com/email-logo-white-2x.png" width="150" alt="LoadBoot" style="display:block;border:0;max-width:150px;height:auto"></td></tr><tr><td style="height:4px;background:#0883F7;background:linear-gradient(90deg,#0883F7,#FC5305);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:32px 36px 6px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p><p style="margin:0 0 16px">Every check call costs minutes that never come back &mdash; multiplied across every load, every day.</p><p style="margin:0 0 16px">On LoadBoot, each load carries <b>live GPS with geofenced arrive and depart timestamps</b>. Your shipper receives one tracking link instead of a phone chain, and &ldquo;where is my freight&rdquo; answers itself &mdash; while detention conversations end with a shared clock instead of two competing stories.</p><p style="margin:0 0 16px">Even if you never use us: requiring arrive/depart timestamps in your rate confirmations is a policy worth adopting this week.</p></td></tr><tr><td align="left" style="padding:10px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/gps-tracking.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">See how live tracking works</span></a></td></tr></table></td></tr><tr><td style="padding:12px 36px 6px;font-size:13.5px;line-height:1.7;color:#64748b">Ready to try it on a live load? <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="color:#0883F7">Post one free</a>.</td></tr><tr><td style="padding:18px 36px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 36px 24px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Partnerships</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d3&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:16px 36px 20px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$T$
where audience='broker' and day=3;

update app_private.outreach_templates set parts=null,
subject='Detention disputes, settled by data',
html=$T$<div style="display:none;max-height:0;overflow:hidden">Pay the real claims fast. Decline the rest with evidence.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:22px 36px"><img src="https://loadboot.com/email-logo-white-2x.png" width="150" alt="LoadBoot" style="display:block;border:0;max-width:150px;height:auto"></td></tr><tr><td style="height:4px;background:#0883F7;background:linear-gradient(90deg,#0883F7,#FC5305);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:32px 36px 6px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p><p style="margin:0 0 16px">Detention is only contentious when both sides are guessing. Three lines in your rate confirmation remove the guesswork: the free time (two hours is standard), the rate per hour after it, and which clock decides.</p><p style="margin:0 0 16px">With geofenced timestamps on every LoadBoot load, <b>legitimate claims are paid quickly and inflated ones are declined with evidence</b> &mdash; and carriers remember who pays fairly. Fair payers get their hardest lanes covered first.</p><p style="margin:0 0 16px">We published the exact detention policy we operate. You are welcome to adopt it as your own, whether or not you ever post with us.</p></td></tr><tr><td align="left" style="padding:10px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/detention-pay-policy.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d4&oc={OC}" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Read the detention policy</span></a></td></tr></table></td></tr><tr><td style="padding:18px 36px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 36px 24px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Partnerships</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d4&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:16px 36px 20px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$T$
where audience='broker' and day=4;

update app_private.outreach_templates set parts=null,
subject='Coverage at 5:40 PM on a Friday — vetted like a Monday',
html=$T$<div style="display:none;max-height:0;overflow:hidden">Booking-time verification holds the same standard at any hour.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:22px 36px"><img src="https://loadboot.com/email-logo-white-2x.png" width="150" alt="LoadBoot" style="display:block;border:0;max-width:150px;height:auto"></td></tr><tr><td style="height:4px;background:#0883F7;background:linear-gradient(90deg,#0883F7,#FC5305);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:32px 36px 6px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p><p style="margin:0 0 16px">Carrier vetting is easy on a Monday morning. It fails at 5:40 PM on a Friday, with freight on the dock and one truck available.</p><p style="margin:0 0 16px">Because verification on LoadBoot runs <b>automatically at the moment of booking</b>, your most pressured cover is vetted to exactly the same standard as your most relaxed one &mdash; authority, insurance, safety record, and VIN-to-COI, every time, at any hour.</p><p style="margin:0 0 16px">Post early with honest appointment windows, and let verified carriers come to you.</p></td></tr><tr><td align="left" style="padding:10px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d5&oc={OC}" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Post your next load free</span></a></td></tr></table></td></tr><tr><td style="padding:18px 36px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 36px 24px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Partnerships</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d5&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:16px 36px 20px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$T$
where audience='broker' and day=5;

update app_private.outreach_templates set parts=null,
subject='Post, cover, confirm, invoice — one screen',
html=$T$<div style="display:none;max-height:0;overflow:hidden">Four systems, one screen — and posting stays free.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:22px 36px"><img src="https://loadboot.com/email-logo-white-2x.png" width="150" alt="LoadBoot" style="display:block;border:0;max-width:150px;height:auto"></td></tr><tr><td style="height:4px;background:#0883F7;background:linear-gradient(90deg,#0883F7,#FC5305);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:32px 36px 6px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p><p style="margin:0 0 16px">Most brokerages run one system to post, another to track, a third for rate confirmations, and a fourth for invoicing &mdash; re-keying the same load into each. Timed end-to-end, that is commonly fifteen minutes of duplicate data entry per load, taken directly out of margin.</p><p style="margin:0 0 16px">LoadBoot consolidates all four steps on one screen: <b>post, cover with a verified carrier, send the rate confirmation, and settle</b>. No integration project, no per-seat license, no posting fees.</p></td></tr><tr><td align="left" style="padding:10px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/payments-settlements.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d6&oc={OC}" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">See how settlements work</span></a></td></tr></table></td></tr><tr><td style="padding:12px 36px 6px;font-size:13.5px;line-height:1.7;color:#64748b">Free to post, always. <a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d6&oc={OC}" style="color:#0883F7">Create your free broker account</a>.</td></tr><tr><td style="padding:18px 36px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 36px 24px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Partnerships</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d6&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:16px 36px 20px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$T$
where audience='broker' and day=6;

update app_private.outreach_templates set parts=null,
subject='A final note from LoadBoot',
html=$T$<div style="display:none;max-height:0;overflow:hidden">Free posting, verified carriers, GPS proof — whenever you are ready.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f8;margin:0"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e2e8f0;font-family:'Segoe UI',Arial,Helvetica,sans-serif"><tr><td style="background:#10223B;padding:22px 36px"><img src="https://loadboot.com/email-logo-white-2x.png" width="150" alt="LoadBoot" style="display:block;border:0;max-width:150px;height:auto"></td></tr><tr><td style="height:4px;background:#0883F7;background:linear-gradient(90deg,#0883F7,#FC5305);font-size:0;line-height:0">&nbsp;</td></tr><tr><td style="padding:32px 36px 6px;color:#0f172a;font-size:15px;line-height:1.75"><p style="margin:0 0 16px">Hello {NAME},</p><p style="margin:0 0 16px">This is the last email in this series &mdash; we will not continue to fill your inbox.</p><p style="margin:0 0 16px">The summary: posting on LoadBoot is <b>free permanently</b>, every carrier arrives FMCSA-verified with the truck&rsquo;s VIN matched to its insurance, and every load carries live GPS proof. Onboarding takes about two minutes &mdash; or skip it entirely and add <b>loads@loadboot.com</b> to your daily load blast, and your freight reaches our carriers with zero change to how you work.</p><p style="margin:0 0 16px">If it is ever useful, our team is one reply &mdash; or one call &mdash; away, at any hour.</p></td></tr><tr><td align="left" style="padding:10px 36px 6px"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#0883F7;border-radius:10px"><a href="https://loadboot.com/create-broker-account.html?utm_source=email&utm_medium=outreach&utm_campaign=broker-d7&oc={OC}" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#ffffff !important;text-decoration:none;border-radius:10px"><span style="color:#ffffff !important;text-decoration:none">Create your free broker account</span></a></td></tr></table></td></tr><tr><td style="padding:18px 36px 0"><div style="border-top:1px solid #e8eef6"></div></td></tr><tr><td style="padding:16px 36px 24px;font-size:13px;line-height:1.9;color:#475569"><b style="color:#10223B">LoadBoot &middot; Broker Partnerships</b><br><a href="https://loadboot.com?utm_source=email&utm_medium=outreach&utm_campaign=broker-d7&oc={OC}" style="color:#0883F7;text-decoration:none"><span style="color:#0883F7 !important;text-decoration:none">loadboot.com</span></a> &middot; +1 (469) 253-7575 &middot; available 24/7 &middot; reply to this email any time</td></tr><tr><td style="background:#f8fafc;padding:16px 36px 20px;font-size:11.5px;line-height:1.75;color:#8a94a6;border-top:1px solid #e8eef6">You are receiving this because {NAME} is listed on the public FMCSA register. If you would prefer not to hear from us, <a href="{UNSUB}" style="color:#8a94a6"><span style="color:#8a94a6 !important">unsubscribe with one click</span></a> and we will stop immediately.<br>LoadBoot LLC &middot; 30 N Gould St Ste N, Sheridan, WY 82801</td></tr></table></td></tr></table>$T$
where audience='broker' and day=7;
